-- Stage 1 only. Self-contained fixtures, always rolled back.
begin;
create extension if not exists pgtap with schema extensions;
select plan(78);
insert into public.colleges(code,name) values('MVP-TEST','MVP Test College');
insert into public.programs(college_id,name) select id,'MVP Test Program' from public.colleges where code = 'MVP-TEST';
insert into public.event_categories(name,slug) values('MVP Test Category','mvp-test');
insert into auth.users(instance_id,id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,is_anonymous,created_at,updated_at)
select '00000000-0000-0000-0000-000000000000',('b1000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'authenticated','authenticated','mvp-' || n || '@test.local',now(),'{}','{"first_name":"MVP","last_name":"Test"}',false,now(),now() from generate_series(1,7) n;
update public.profiles set student_id = 'MVP-' || right(id::text,4),college_id = (select id from public.colleges where code = 'MVP-TEST'),program_id = (select id from public.programs where name = 'MVP Test Program'),year_level = 1,avatar_path = id::text || '/photo.png',privacy_consented_at = now(),privacy_notice_version = '2026-10-draft' where id::text like 'b1000000-%' and id <> 'b1000000-0000-4000-8000-000000000007';
update public.profiles set is_admin = true where id in ('b1000000-0000-4000-8000-000000000002','b1000000-0000-4000-8000-000000000003');
update public.profiles set organizer_status = 'active',organizer_since = now() where id = 'b1000000-0000-4000-8000-000000000004';
insert into storage.objects(bucket_id,name,owner_id) values('organizer-requirements','b1000000-0000-4000-8000-000000000001/proof.pdf','b1000000-0000-4000-8000-000000000001');
insert into public.organizer_applications(id,applicant_id,organization_name,position_title,contact_number,reason,proof_document_path,privacy_notice_version) values('ba000000-0000-4000-8000-000000000003','b1000000-0000-4000-8000-000000000003','MVP Admin Council','President','09123456789',repeat('reason ',10),'admin/proof.pdf','2026-10-draft');
-- Historical application fixture; no submission RPC is used.
insert into public.organizer_applications(id,applicant_id,organization_name,position_title,contact_number,reason,proof_document_path,privacy_notice_version)
values('ba000000-0000-4000-8000-000000000001','b1000000-0000-4000-8000-000000000001','MVP Council','President','09123456789',repeat('reason ',10),'b1000000-0000-4000-8000-000000000001/proof.pdf','2026-10-draft');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
set local role authenticated;
select is(public.submit_organizer_application(jsonb_build_object('organization_name','MVP Council','position_title','President','contact_number','09123456789','reason',repeat('reason ',10),'proof_document_path','b1000000-0000-4000-8000-000000000001/proof.pdf','privacy_notice_version','2026-10-draft','consent',false))->>'code','workflow_retired','application submissions are closed even without consent');
select is(public.submit_organizer_application(jsonb_build_object('organization_name','MVP Council','position_title','President','contact_number','09123456789','reason',repeat('reason ',10),'proof_document_path','someone-else/proof.pdf','privacy_notice_version','2026-10-draft','consent',true))->>'code','workflow_retired','foreign proof cannot bypass retirement');
select is(public.submit_organizer_application(jsonb_build_object('organization_name','MVP Council','position_title','President','contact_number','09123456789','reason',repeat('reason ',10),'proof_document_path','b1000000-0000-4000-8000-000000000001/proof.pdf','privacy_notice_version','2026-10-draft','consent',true))->>'code','workflow_retired','complete participant cannot apply');
select is(public.submit_organizer_application('{"privacy_notice_version":"2026-10-draft","consent":true}')->>'code','workflow_retired','repeated submission remains closed');
select is((select count(*)::int from public.organizer_applications),1,'applicant sees only own application');
select is(public.withdraw_organizer_application('ba000000-0000-4000-8000-000000000001'),'workflow_retired','historical withdrawal is closed');
select is((select status::text from public.organizer_applications where id = 'ba000000-0000-4000-8000-000000000001'),'pending','historical application status is unchanged');
select throws_ok($$ insert into public.organizer_applications default values $$,'42501',null,'direct submission is forbidden');
select throws_ok($$ update public.organizer_applications set status = 'approved' where applicant_id = auth.uid() $$,'42501',null,'direct application approval is forbidden');
select throws_ok($$ insert into storage.objects(bucket_id,name,owner_id) values('organizer-requirements','b1000000-0000-4000-8000-000000000001/new-proof.pdf','b1000000-0000-4000-8000-000000000001') $$,'42501',null,'new proof uploads are forbidden');
select is(public.review_organizer_application('ba000000-0000-4000-8000-000000000003','approved'), 'workflow_retired','participant cannot review');
select throws_ok($$ update public.profiles set organizer_status = 'active' where id = auth.uid() $$,'42501',null,'organizer role not directly writable');
select throws_ok($$ update public.profiles set is_admin = true where id = auth.uid() $$,'42501',null,'admin role not directly writable');
select is(public.save_event(null,'{"title":"Unauthorized event"}')->>'code','not_permitted','participant cannot create event');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000003","role":"authenticated","is_anonymous":false}',true);
select is(public.review_organizer_application('ba000000-0000-4000-8000-000000000003','approved'),'workflow_retired','admin cannot approve own historical application');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is(public.review_organizer_application((select id from public.organizer_applications where applicant_id = 'b1000000-0000-4000-8000-000000000001'),'rejected',''),'workflow_retired','historical rejection is closed');
select is(public.review_organizer_application((select id from public.organizer_applications where applicant_id = 'b1000000-0000-4000-8000-000000000001'),'approved'),'workflow_retired','admin cannot grant access through historical approval');
select is((select organizer_status::text from public.profiles where id = 'b1000000-0000-4000-8000-000000000001'),'none','retired approval leaves participant privileges unchanged');
select is(public.review_organizer_application((select id from public.organizer_applications where applicant_id = 'b1000000-0000-4000-8000-000000000001'),'approved'),'workflow_retired','repeated review remains closed');
select is((select count(*)::int from public.audit_logs where action = 'organizer.approved' and actor_id = auth.uid()),0,'retired approval creates no misleading audit entry');
select is(public.set_organizer_status('b1000000-0000-4000-8000-000000000001','active','Attempt promotion'),'invalid_status','status management cannot substitute for a promotion workflow');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
-- Isolated event-management fixture; not a live grant or application approval.
reset role;
update public.profiles set organizer_status = 'active',organizer_since = now() where id = 'b1000000-0000-4000-8000-000000000001';
set local role authenticated;
select is(public.save_event(null,'{"title":"MVP Minimal Draft"}')->>'code','ok','organizer creates minimal draft');
select is(public.publish_event((select id from public.events where title = 'MVP Minimal Draft')),'incomplete_event','cannot publish incomplete draft');
select throws_ok($$ update public.events set status = 'published' where title = 'MVP Minimal Draft' $$,'42501',null,'event state cannot be written directly');
select throws_ok($$ update public.events set organizer_id = auth.uid(),invite_code = 'HACKCODE' where title = 'MVP Minimal Draft' $$,'42501',null,'ownership and invite cannot be written directly');
reset role;
insert into public.events(id,organizer_id,title,description,venue,category_id,starts_at,ends_at,registration_opens_at,registration_closes_at,capacity,approval_mode,visibility)
select ('be000000-0000-4000-8000-' || lpad(n::text,12,'0'))::uuid,'b1000000-0000-4000-8000-000000000001','MVP Event ' || n,repeat('description ',3),'University Hall',(select id from public.event_categories where slug = 'mvp-test'),now()+interval '2 days',now()+interval '2 days 2 hours',now()-interval '1 day',now()+interval '1 day',case when n = 1 then 1 else 10 end,case when n = 2 then 'manual'::public.approval_mode else 'automatic'::public.approval_mode end,case when n = 3 then 'unlisted'::public.event_visibility else 'public'::public.event_visibility end from generate_series(1,4) n;
set local role authenticated;
select is(public.publish_event('be000000-0000-4000-8000-000000000001'),'ok','organizer publishes without admin event approval');
select is(public.publish_event('be000000-0000-4000-8000-000000000002'),'ok','manual approval event published');
select is(public.publish_event('be000000-0000-4000-8000-000000000003'),'ok','unlisted event published');
select ok((select invite_code ~ '^[ABCDEFGHJKMNPQRSTUVWXYZ23456789]{8}$' from public.events where id = 'be000000-0000-4000-8000-000000000001'),'invite uses approved alphabet');
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'own_event','organizer cannot register for own event');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000004","role":"authenticated","is_anonymous":false}',true);
select is(public.publish_event('be000000-0000-4000-8000-000000000004'),'not_found','other organizer cannot publish draft');
select is(public.save_event('be000000-0000-4000-8000-000000000001','{"title":"Foreign edit"}')->>'code','not_found','other organizer cannot edit event');
select is((select count(*)::int from public.events where id = 'be000000-0000-4000-8000-000000000004'),0,'foreign draft hidden by RLS');
select is((select count(*)::int from storage.objects where bucket_id = 'organizer-requirements' and name = 'b1000000-0000-4000-8000-000000000001/proof.pdf'),0,'proof hidden from other organizer');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000007","role":"authenticated","is_anonymous":false}',true);
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'profile_incomplete','incomplete participant cannot register');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000005","role":"authenticated","is_anonymous":false}',true);
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'approved','automatic registration approved');
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'approved','duplicate request is idempotent');
select is((select count(*)::int from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000001'),1,'one registration row per event/user');
select throws_ok($$ update public.profiles set student_id = 'MVP-CHANGED' where id = auth.uid() $$,'23514',null,'approved registration locks student ID');
select throws_ok($$ update public.profiles set avatar_path = id::text || '/changed.png' where id = auth.uid() $$,'23514',null,'approved registration locks photo');
select lives_ok($$ update public.profiles set first_name = 'Corrected' where id = auth.uid() $$,'names remain editable');
select throws_ok($$ insert into public.event_registrations(event_id,user_id,status) values('be000000-0000-4000-8000-000000000002',auth.uid(),'approved') $$,'42501',null,'registration writes require RPC');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000006","role":"authenticated","is_anonymous":false}',true);
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'event_full','capacity enforced');
select is((select count(*)::int from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000001'),0,'other participant registration hidden');
select is(public.register_for_event('be000000-0000-4000-8000-000000000002'),'pending','manual registration waits for approval');
select is(public.decide_registration((select id from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000002'),'approved'),'not_permitted','participant cannot approve registration');
select is(public.register_for_event('be000000-0000-4000-8000-000000000003'),'approved','known unlisted URL permits registration');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
select is(public.decide_registration((select id from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000002'),'approved'),'ok','owner approves pending registration');
select ok(private.can_view_profile('b1000000-0000-4000-8000-000000000005'),'owner may read own event registrant profile');
select is((select count(*)::int from public.profiles where id = 'b1000000-0000-4000-8000-000000000007'),0,'unrelated profile remains hidden');
select is(public.delete_event_draft('be000000-0000-4000-8000-000000000001'),'not_found','published event cannot be deleted');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000005","role":"authenticated","is_anonymous":false}',true);
select is(public.cancel_registration('be000000-0000-4000-8000-000000000001'),'ok','participant cancels before start');
select lives_ok($$ update public.profiles set student_id = 'MVP-UNLOCKED' where id = auth.uid() $$,'identity unlocked after cancellation');
select is(public.register_for_event('be000000-0000-4000-8000-000000000001'),'approved','cancelled registration can register again');
select is((select count(*)::int from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000001'),1,'re-registration reuses row');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is(public.set_organizer_status('b1000000-0000-4000-8000-000000000001','suspended','Review requested'),'ok','admin suspends organizer');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
select is(public.save_event(null,'{"title":"Suspended draft"}')->>'code','not_permitted','suspended organizer cannot create');
select is(public.publish_event('be000000-0000-4000-8000-000000000004'),'not_permitted','suspended organizer cannot publish');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":false}',true);
select is(public.set_organizer_status('b1000000-0000-4000-8000-000000000001','active','Review cleared'),'ok','admin reinstates organizer');
select is(public.cancel_event('be000000-0000-4000-8000-000000000001',''),'reason_required','admin cancellation requires reason');
select is(public.cancel_event('be000000-0000-4000-8000-000000000001','Duplicate event'),'ok','admin can cancel published event');
select is((select cancelled_by from public.events where id = 'be000000-0000-4000-8000-000000000001'),auth.uid(),'cancelling admin recorded');
select is((select count(*)::int from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000001'),0,'admin has no registration management access');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
select is((select count(*)::int from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000001'),1,'cancelled event keeps registrations');
select is(public.save_event('be000000-0000-4000-8000-000000000001','{"title":"Terminal edit"}')->>'code','terminal_event','terminal event cannot be edited');
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000002","role":"authenticated","is_anonymous":true}',true);
select is(public.review_organizer_application('ba000000-0000-4000-8000-000000000003','approved'),'workflow_retired','anonymous admin subject cannot use retired review');
select is(public.register_for_event('be000000-0000-4000-8000-000000000002'),'not_permitted','anonymous registration denied');
select is((select count(*)::int from public.events),0,'anonymous event read denied');
reset role;
update public.events set status = 'completed',completed_at = now()-interval '31 days' where id = 'be000000-0000-4000-8000-000000000002';
select set_config('request.jwt.claims','{"sub":"b1000000-0000-4000-8000-000000000001","role":"authenticated","is_anonymous":false}',true);
set local role authenticated;
select ok(not private.can_view_profile('b1000000-0000-4000-8000-000000000006') or exists(select 1 from public.event_registrations where event_id = 'be000000-0000-4000-8000-000000000003'),'access window tied to remaining active event');
reset role;
update public.events set status = 'completed',completed_at = now()-interval '31 days' where id = 'be000000-0000-4000-8000-000000000003';
set local role authenticated;
select ok(not private.can_view_profile('b1000000-0000-4000-8000-000000000006'),'registrant access expires after 30 days');
reset role;
set local role anon;
select is((select count(*)::int from public.get_public_event_preview('be000000-0000-4000-8000-000000000001')),1,'public cancelled event gets limited preview');
select is((select count(*)::int from public.get_public_event_preview('be000000-0000-4000-8000-000000000004')),0,'draft preview hidden');
select is((select count(*)::int from public.get_public_event_preview('be000000-0000-4000-8000-000000000003')),0,'unlisted preview hidden');
select is((select count(*)::int from public.get_public_event_preview('00000000-0000-4000-8000-000000000000')),0,'unknown preview identical to private');
select throws_ok($$ select * from public.events $$,'42501',null,'signed-out table access denied');
select throws_ok($$ select * from public.event_registrations $$,'42501',null,'signed-out registration access denied');
select throws_ok($$ select public.register_for_event('be000000-0000-4000-8000-000000000002') $$,'42501',null,'signed-out mutation denied');
reset role;
select is((select proargnames[2:]::text from pg_proc where oid = 'public.get_public_event_preview(uuid)'::regprocedure),'{title,description,category_name,host_college_name,starts_at,ends_at,venue,banner_path,organization_name,status_label}','public preview exposes exact whitelist');
select * from finish();
rollback;
